import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Slot } from "radix-ui";

import { Separator } from "./separator";

import { useDescendantFlags } from "../lib/descendant-flags";
import { cn } from "../lib/utils";

import controlStyles from "./controls.module.css";

const buttonGroupVariants = cva(
  "group/button-group flex w-fit items-stretch *:focus-visible:relative *:focus-visible:z-10 data-[has-group]:gap-2 [&>[data-slot=select-trigger]:not([class*='w-'])]:w-fit [&>input]:flex-1",
  {
    variants: {
      orientation: {
        horizontal:
          "[&>*:not(:first-child)]:rounded-l-none [&>*:not(:first-child)]:border-l-0 [&>*:not(:last-child)]:rounded-r-none",
        vertical:
          "flex-col [&>*:not(:first-child)]:rounded-t-none [&>*:not(:first-child)]:border-t-0 [&>*:not(:last-child)]:rounded-b-none"
      }
    },
    defaultVariants: {
      orientation: "horizontal"
    }
  }
);

const groupFlags = { "data-has-group": ':scope > [data-slot="button-group"]' };
const groupWatch = {
  subtree: false,
  marks: {
    "data-between-outlines": `:scope > [data-variant="outline"] + .${controlStyles.groupSeparator}:has(+ [data-variant="outline"])`
  }
};

function ButtonGroup({
  className,
  orientation = "horizontal",
  variant = "attached",
  label,
  onKeyDown,
  onFocus,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> &
  VariantProps<typeof buttonGroupVariants> & {
    variant?: "attached" | "toolbar" | "spaced";
    label?: string;
  } & { ref?: React.Ref<React.ComponentRef<"div">> }) {
  const group = React.useRef<HTMLDivElement | null>(null);
  const markRef = useDescendantFlags<HTMLDivElement>(groupFlags, groupWatch);
  const controls = () =>
    Array.from(
      group.current?.querySelectorAll<HTMLElement>(
        'button:not(:disabled), a[href], [role="button"]:not([aria-disabled="true"])'
      ) ?? []
    );
  React.useLayoutEffect(() => {
    if (variant !== "toolbar") return;
    const nodes = controls();
    const focused = nodes.find((node) => node === document.activeElement) ?? nodes[0];
    nodes.forEach((node) => {
      node.tabIndex = node === focused ? 0 : -1;
    });
  });
  return (
    <div
      ref={(node) => {
        group.current = node;
        markRef(node);
        if (typeof ref === "function") ref(node);
        else if (ref) {
          const forwarded = ref;
          forwarded.current = node;
        }
      }}
      onFocus={(event) => {
        onFocus?.(event);
        if (variant === "toolbar")
          controls().forEach((node) => {
            node.tabIndex = node === event.target ? 0 : -1;
          });
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (
          event.defaultPrevented ||
          variant !== "toolbar" ||
          event.altKey ||
          event.ctrlKey ||
          event.metaKey ||
          (event.target instanceof HTMLElement && event.target.closest("input, textarea, select"))
        )
          return;
        const nodes = controls();
        const index = nodes.findIndex((node) => node === event.target);
        const previous = orientation === "vertical" ? "ArrowUp" : "ArrowLeft";
        const next = orientation === "vertical" ? "ArrowDown" : "ArrowRight";
        const target =
          event.key === "Home"
            ? nodes[0]
            : event.key === "End"
              ? nodes[nodes.length - 1]
              : event.key === previous
                ? nodes[(index - 1 + nodes.length) % nodes.length]
                : event.key === next
                  ? nodes[(index + 1) % nodes.length]
                  : undefined;
        if (target) {
          event.preventDefault();
          target.focus();
        }
      }}
      role={variant === "toolbar" ? "toolbar" : "group"}
      aria-label={label}
      data-variant={variant}
      data-slot="button-group"
      data-orientation={orientation}
      className={cn(
        variant === "attached"
          ? buttonGroupVariants({ orientation })
          : cn(
              "inline-flex",
              orientation === "vertical" ? "flex-col items-stretch" : "items-center"
            ),
        controlStyles.group,
        className
      )}
      {...props}
    />
  );
}
ButtonGroup.displayName = "ButtonGroup";

function ButtonGroupText({
  className,
  asChild = false,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & {
  asChild?: boolean;
} & { ref?: React.Ref<React.ComponentRef<"div">> }) {
  const Comp = asChild ? Slot.Root : "div";

  return (
    <Comp
      ref={ref}
      data-slot="button-group-text"
      className={cn(controlStyles.groupText, className)}
      {...props}
    />
  );
}
ButtonGroupText.displayName = "ButtonGroupText";

function ButtonGroupSeparator({
  className,
  orientation = "vertical",
  ref,
  ...props
}: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      ref={ref}
      data-slot="button-group-separator"
      orientation={orientation}
      className={cn(controlStyles.groupSeparator, className)}
      {...props}
    />
  );
}
ButtonGroupSeparator.displayName = "ButtonGroupSeparator";

export { ButtonGroup, ButtonGroupSeparator, ButtonGroupText, buttonGroupVariants };
